import{n as e,t}from"./helpers-0sYvox5E.js";var n=[t({id:`lookout-tower-001`,building:`lookout-tower`,d:1,stem:`A security team discovers that an Amazon EC2 instance was terminated. The team needs to find out which IAM user made the API call and when. Which service should the team use to answer this question?`,correct:[`AWS CloudTrail`,`CloudTrail records actions taken by a user, role, or service as events, so it shows who made the call and when.`],wrong:[[`Amazon CloudWatch metrics`,`Metrics track performance data such as CPU use and do not record which identity made an API call.`],[`AWS Config`,`AWS Config records how a resource was configured over time, but the question is about the identity that made the call.`],[`Amazon CloudWatch alarms`,`An alarm reacts to a metric crossing a threshold and does not record who performed an action.`]],slot:0,evidence:[`cloudtrail-what-is|Actions taken by a user, role, or an AWS service are recorded as events in CloudTrail.`,`cloudtrail-what-is|You can identify who or what took which action, what resources were acted upon, when the event occurred, and other details to help you analyze and respond to activity in your AWS account.`]}),t({id:`lookout-tower-002`,building:`lookout-tower`,d:1,stem:`An operations team wants to be notified by email whenever the CPU utilization of a production Amazon EC2 instance stays above a set limit. Which solution is the SIMPLEST way to meet this requirement?`,correct:[`Create an Amazon CloudWatch alarm on the CPU metric that notifies an Amazon SNS topic`,`An alarm watches a metric and sends a notification when its threshold is breached.`],wrong:[[`Create an AWS CloudTrail trail that delivers events to Amazon S3`,`A trail records API activity and does not watch the CPU metric of an instance.`],[`Create an AWS Config rule that evaluates the instance type`,`A Config rule evaluates configuration settings, not a running performance value such as CPU use.`],[`Set a retention period on the instance log group in Amazon CloudWatch Logs`,`Retention controls how long log events are kept and does not notify anyone about CPU use.`]],slot:1,evidence:[`cw-alarms|You can create alarms that watch metrics and send notifications or automatically make changes to the resources you are monitoring when a threshold is breached.`]}),t({id:`lookout-tower-003`,building:`lookout-tower`,d:2,stem:`A company requires that every Amazon EBS volume in its account stays encrypted. The company wants resources that break this setting to be flagged as noncompliant automatically, with the LEAST ongoing effort. Which solution meets these requirements?`,correct:[`Create an AWS Config rule that represents the encryption setting`,`A Config rule states the ideal configuration, and AWS Config flags resources that violate it as noncompliant.`],wrong:[[`Create an Amazon CloudWatch alarm on the volume read throughput metric`,`A metric alarm watches performance values and cannot tell whether a volume is encrypted.`],[`Search the AWS CloudTrail event history every week for volume creation calls`,`It is a manual process with ongoing effort, and it does not flag noncompliant resources automatically.`],[`Create a metric filter on an Amazon CloudWatch Logs log group`,`A metric filter turns log events into metrics and does not evaluate the configuration of volumes.`]],slot:2,evidence:[`config-rules|You do this by creating AWS Config rules, which represent your ideal configuration settings.`,`config-what-is|When AWS Config detects that a resource violates the conditions in one of your rules, AWS Config flags the resource as noncompliant and sends a notification.`]}),t({id:`lookout-tower-004`,building:`lookout-tower`,d:2,stem:`During an audit, a company must show how the configuration of a security group and its related resources looked six months ago and how it changed since then. Which service BEST provides this information?`,correct:[`AWS Config`,`It keeps the configuration of resources and their relationships and shows how they changed over time.`],wrong:[[`AWS CloudTrail Event history`,`It covers only the past 90 days of management events, and it records API activity, not the configuration of resources.`],[`Amazon CloudWatch dashboards`,`Dashboards visualize metrics and logs and do not hold the configuration history of resources.`],[`Amazon CloudWatch alarms`,`Alarms react to a metric threshold and do not record past configurations.`]],slot:3,evidence:[`config-what-is|how they were configured in the past so that you can see how the configurations and relationships change over time`,`cloudtrail-what-is|The Event history provides a viewable, searchable, downloadable, and immutable record of the past 90 days of management events in an AWS Region.`]}),t({id:`lookout-tower-005`,building:`lookout-tower`,d:2,stem:`A company must keep a record of all management API calls made in its account for 13 months, stored in Amazon S3, with the LOWEST operational overhead. Which solution meets these requirements?`,correct:[`Create an AWS CloudTrail trail that delivers the events to an Amazon S3 bucket`,`A trail captures AWS activity and stores the events in an S3 bucket, so the record lasts as long as the bucket data does.`],wrong:[[`Rely on the AWS CloudTrail Event history`,`Event history shows only the past 90 days of management events, which is shorter than 13 months.`],[`Turn on the AWS Config configuration recorder`,`It records resource configurations and relationships, not a record of the API calls made.`],[`Create an Amazon CloudWatch dashboard that shows API activity`,`A dashboard displays metrics and does not keep a record of each API call for 13 months.`]],slot:0,evidence:[`cloudtrail-what-is|Trails – Trails capture a record of AWS activities, delivering and storing these events in an Amazon S3 bucket, with optional delivery to CloudWatch Logs and Amazon EventBridge.`,`cloudtrail-what-is|The Event history provides a viewable, searchable, downloadable, and immutable record of the past 90 days of management events in an AWS Region.`]}),t({id:`lookout-tower-006`,building:`lookout-tower`,d:2,stem:`An application sends its logs to an Amazon CloudWatch Logs log group, and the logs are currently kept forever. Compliance requires deleting log events after 90 days. Which solution meets this requirement with the LEAST effort?`,correct:[`Set a 90-day retention policy on the log group`,`Retention is a log group setting that applies to all log streams in the group, and old events then expire without any code.`],wrong:[[`Set a 90-day retention policy on each log stream separately`,`Retention settings are assigned to log groups, not to individual log streams.`],[`Create an AWS CloudTrail trail with a 90-day setting`,`A trail records API activity and does not control how long CloudWatch Logs keeps log events.`],[`Write a scheduled script that deletes old log events from the log group`,`It would work, but it adds code to build and run, which is more effort than a built-in setting.`]],slot:1,evidence:[`cwl-what-is|By default, logs are kept indefinitely and never expire.`,`cwl-concepts|Just like metric filters, retention settings are also assigned to log groups, and the retention assigned to a log group is applied to their log streams.`]}),t({id:`lookout-tower-007`,building:`lookout-tower`,d:3,stem:`An application writes ERROR lines to an Amazon CloudWatch Logs log group. The team wants an email whenever the number of ERROR lines passes a threshold within five minutes, with the LEAST development effort. Which solution meets these requirements?`,correct:[`Create a metric filter on the log group, a CloudWatch alarm on the metric, and an Amazon SNS topic for the email`,`A metric filter turns matching log events into a metric, and an alarm on that metric notifies an SNS topic when the threshold is breached.`],wrong:[[`Create an AWS CloudTrail trail and search it for the word ERROR`,`A trail records API activity of the account, not the log lines that an application writes.`],[`Create an AWS Config rule that matches the word ERROR in the logs`,`Config rules evaluate resource configuration settings and do not read application log lines.`],[`Write a function that reads the log group every minute and counts the lines`,`It would work, but it needs custom code that a metric filter and alarm make unnecessary.`]],slot:2,evidence:[`cwl-concepts|You can use metric filters to extract metric observations from ingested events and transform them to data points in a CloudWatch metric.`,`cw-alarms|The action can be sending a notification to an Amazon SNS topic, performing an Amazon EC2 action or an Amazon EC2 Auto Scaling action`]}),e({id:`lookout-tower-008`,building:`lookout-tower`,d:3,stem:`A company has two requirements. First, it must be able to find out which user changed a security group rule. Second, it must automatically flag security groups that break its rule against opening SSH to the internet. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Use AWS CloudTrail to record the API calls that change security groups`,`CloudTrail records the actions taken by a user, role, or service, so it answers who made the change.`],[`Create an AWS Config rule that evaluates security group settings`,`A Config rule represents the ideal configuration, and resources that violate it are flagged as noncompliant.`]],wrong:[[`Create an Amazon CloudWatch alarm on the NetworkIn metric of the instances`,`A metric alarm watches traffic volume and shows neither the user who made a change nor the security group configuration.`],[`Build an Amazon CloudWatch dashboard of EC2 CPU utilization`,`A dashboard visualizes metrics and does not identify users or evaluate configuration.`],[`Set a one-year retention period on an Amazon CloudWatch Logs log group`,`Retention only decides how long log events are kept and neither records API callers nor evaluates security groups.`]],slots:[0,2],evidence:[`cloudtrail-what-is|Actions taken by a user, role, or an AWS service are recorded as events in CloudTrail.`,`config-what-is|When AWS Config detects that a resource violates the conditions in one of your rules, AWS Config flags the resource as noncompliant and sends a notification.`]}),t({id:`lookout-tower-009`,building:`lookout-tower`,d:3,stem:`A company has a multi-Region AWS CloudTrail trail with its default settings. An auditor now needs a record of who reads and deletes objects in one Amazon S3 bucket that holds regulated data. The company wants to keep the number of logged events as low as possible. Which solution meets these requirements?`,correct:[`Add data events for only that bucket to the trail`,`Object-level operations such as GetObject and DeleteObject are data events, which are not logged by default, and limiting them to one bucket keeps the volume low.`],wrong:[[`Add data events for all S3 buckets to the trail`,`It records the object-level activity, but data events are high-volume, so logging every bucket exceeds the low volume the company wants.`],[`Enable Insights events on the trail`,`Insights events analyze management events for unusual API call rates and do not record object-level reads and deletes.`],[`Use the CloudTrail Event history for the bucket`,`Event history holds management events only, so it does not contain GetObject or DeleteObject calls.`]],slot:3,evidence:[`cloudtrail-concepts|By default, trails and event data stores log management events, but not data or Insights events.`,`cloudtrail-concepts|Example data events include: Amazon S3 object-level API activity (for example, GetObject, DeleteObject, and PutObject API operations) on objects in S3 buckets.`,`cloudtrail-concepts|Data events are often high-volume activities.`]}),e({id:`lookout-tower-010`,building:`lookout-tower`,d:2,stem:`An operations team creates an Amazon CloudWatch alarm on the average CPU utilization of an Amazon EC2 Auto Scaling group. When the threshold is breached, the alarm must alert the engineers and add capacity to the group. Which TWO alarm actions meet these requirements? (Choose two.)`,correct:[[`Send a notification to an Amazon SNS topic`,`An alarm action can send a notification to an Amazon SNS topic, which alerts the engineers.`],[`Perform an Amazon EC2 Auto Scaling action`,`An alarm action can be an Amazon EC2 Auto Scaling action, which adds capacity to the group.`]],wrong:[[`Evaluate the Auto Scaling group against an AWS Config rule`,`This is not an alarm action; Config rules evaluate configuration settings separately from metric alarms.`],[`Record the breach as an AWS CloudTrail data event`,`This is not an alarm action, and data events describe resource operations such as S3 object requests.`],[`Change the retention period of a CloudWatch Logs log group`,`This is not an alarm action, and it neither alerts the engineers nor adds capacity.`]],slots:[4,1],evidence:[`cw-alarms|The action can be sending a notification to an Amazon SNS topic, performing an Amazon EC2 action or an Amazon EC2 Auto Scaling action`]})],r=[t({id:`pillar-plaza-001`,building:`pillar-plaza`,d:1,stem:`After a recent outage, a payments company starts a Well-Architected review. The reviewers want to focus on whether the workload performs its intended function correctly and consistently when customers expect it, including how it is operated and tested through its lifecycle. Which pillar is the BEST match for this focus?`,correct:[`Reliability`,`The Reliability pillar is defined as the ability of a workload to perform its intended function correctly and consistently when it is expected to, including operating and testing it through its lifecycle.`],wrong:[[`Security`,`The Security pillar is about protecting data, systems and assets. It does not describe consistent correct function when users expect it.`],[`Performance efficiency`,`This pillar is about using cloud resources efficiently to meet performance requirements as demand changes, not about correct and consistent function after failures.`],[`Cost optimization`,`This pillar is about running systems to deliver business value at the lowest price point, which is not the focus described.`]],slot:0,evidence:[`waf-reliability|The Reliability pillar encompasses the ability of a workload to perform its intended function correctly and consistently when it’s expected to.`,`waf-reliability|This includes the ability to operate and test the workload through its total lifecycle.`]}),t({id:`pillar-plaza-002`,building:`pillar-plaza`,d:2,stem:`A company runs development and test environments on Amazon EC2 around the clock, although developers use them only during the work week. The architecture review board wants a change that follows the Cost Optimization design principles with the LEAST effort spent on forecasting. Which action is the BEST fit?`,correct:[`Stop the environments when they are not in use and start them again when needed`,`Adopting a consumption model means paying only for the compute you need and changing usage with business requirements, and the framework gives stopping unused environments as the example.`],wrong:[[`Buy capacity for the expected peak of the year and keep it running continuously`,`This relies on forecasting and pays for idle capacity, which is the opposite of a consumption model.`],[`Add a standby copy of each environment in a second Availability Zone`,`This targets resilience and adds running resources, so it does not reduce cost.`],[`Move every environment to the largest instance size to finish test runs sooner`,`A larger size may help speed, but the environments still run when nobody uses them and the cost grows.`]],slot:1,evidence:[`waf-cost-dp|Pay only for the computing resources that you require and increase or decrease usage depending on business requirements, not by using elaborate forecasting.`,`waf-cost-dp|You can stop these resources when they are not in use`]}),t({id:`pillar-plaza-003`,building:`pillar-plaza`,d:2,stem:`A company runs a fleet of Amazon EC2 instances that average low CPU utilization all day. A new sustainability goal asks the team to reduce the energy the workload needs. Which action BEST follows the Sustainability design principles?`,correct:[`Right-size the instances and use Auto Scaling so fewer, busier instances run`,`Right-sizing and raising utilization reduces idle resources and the total energy needed to power the workload.`],wrong:[[`Keep the current fleet and add the same number of idle instances as spare capacity`,`More idle resources increase the energy needed, which works against maximizing utilization.`],[`Provision the fleet for the highest yearly peak and leave it fixed in size`,`A fixed peak-sized fleet keeps utilization low, so it does not reduce idle capacity.`],[`Run a full duplicate of the fleet in a second Region at all times`,`A permanently running duplicate doubles the idle resources, so it fails the goal of reducing energy.`]],slot:2,evidence:[`waf-sus-dp|Right-size workloads and implement efficient design to verify high utilization and maximize the energy efficiency of the underlying hardware.`,`waf-sus-dp|At the same time, reduce or minimize idle resources, processing, and storage to reduce the total energy required to power your workload.`,`waf-sustainability|The Sustainability pillar focuses on environmental impacts, especially energy consumption and efficiency, since they are important levers for architects to inform direct action to reduce resource usage.`]}),e({id:`pillar-plaza-004`,building:`pillar-plaza`,d:2,tags:[],stem:`A security architect is reviewing a new workload against the Security pillar design principles. Which TWO changes BEST align with those principles? (Choose two.)`,correct:[[`Centralize identity management and stop relying on long-term static credentials`,`Centralized identity and the removal of long-term static credentials are part of a strong identity foundation.`],[`Apply several security controls at the network edge, the VPC, the load balancer and each instance`,`A defense in depth approach applies multiple controls at every layer instead of one boundary.`]],wrong:[[`Give developers direct access to production data so they can fix issues faster`,`The principle is to keep people away from data and reduce direct access or manual processing, so this raises risk.`],[`Rely on one perimeter firewall as the only control`,`A single control at one layer fails the principle of applying security at all layers.`],[`Turn off activity logging to reduce noise`,`The principle is to maintain traceability by monitoring, alerting and auditing actions, so this removes visibility.`],[`Review configuration by hand once a year`,`The principle is to automate security best practices so controls scale, which an annual manual review does not do.`]],slots:[0,3],evidence:[`waf-sec-dp|Centralize identity management, and aim to eliminate reliance on long-term static credentials.`,`waf-sec-dp|Apply a defense in depth approach with multiple security controls.`]}),t({id:`pillar-plaza-005`,building:`pillar-plaza`,d:2,stem:`A company serves its web application from one very large Amazon EC2 instance. Every failure or reboot takes the whole site down. The reviewers want a design change that follows the Reliability design principles. Which solution is the BEST fit?`,correct:[`Use several smaller instances in an Auto Scaling group behind a load balancer`,`Spreading requests across multiple smaller resources reduces the impact of a single failure on the overall workload.`],wrong:[[`Move the application to the largest available instance size in its current zone`,`One bigger instance is still a single point of failure, so a failure still takes the site down.`],[`Attach additional EBS volumes to the existing instance to add more storage`,`More volumes add storage, not a second compute resource, so the instance remains a single point of failure.`],[`Take a manual snapshot of the instance every week and keep it in Amazon S3`,`Snapshots help recovery, but the site still goes down on every failure and recovery is manual.`]],slot:3,evidence:[`waf-rel-dp|Replace one large resource with multiple small resources to reduce the impact of a single failure on the overall workload.`,`waf-rel-dp|Distribute requests across multiple, smaller resources to verify that they don’t share a common point of failure.`]}),t({id:`pillar-plaza-006`,building:`pillar-plaza`,d:3,stem:`A team ships one large manual release every month. When a release fails, reversing it takes hours and affects many components. Management wants to reduce the blast radius of changes and speed up recovery, in line with the Operational excellence design principles. Which approach BEST meets these requirements?`,correct:[`Define the workload as code and deploy small changes through automation`,`Smaller incremental changes with automated deployment reduce the blast radius and allow faster reversal when a failure occurs.`],wrong:[[`Combine several months of changes into one larger quarterly release`,`Larger batches widen the blast radius and make reversal harder, which fails both requirements.`],[`Add a second manual approval step before each monthly release goes out`,`An extra approval adds delay but the release stays large and manual, so a failure still affects many components.`],[`Deploy the monthly release to a second Availability Zone as well`,`A second zone adds capacity for failure of a zone, but a faulty release is still large and slow to reverse.`]],slot:0,evidence:[`waf-oe-dp|Automated deployment techniques together with smaller, incremental changes reduces the blast radius and allows for faster reversal when failures occur.`,`waf-oe-dp|You can define your entire workload and its operations (applications, infrastructure, configuration, and procedures) as code, and update it.`]}),t({id:`pillar-plaza-007`,building:`pillar-plaza`,d:1,stem:`A company wants to evaluate its workload architecture against the pillars of the Well-Architected Framework from the AWS Management Console, then save milestones and track improvements over time, with the LEAST custom tooling. Which AWS service should the company use?`,correct:[`AWS Well-Architected Tool`,`The tool provides a framework for evaluating a cloud architecture in the console and lets you save point-in-time milestones and track changes to measure progress.`],wrong:[[`AWS Config with managed rules`,`AWS Config records and evaluates resource configurations against rules, but it does not run a pillar-based architecture review.`],[`Amazon Inspector vulnerability scans`,`Amazon Inspector scans workloads for vulnerabilities, which is not an architecture review against the pillars.`],[`AWS CloudTrail event history`,`AWS CloudTrail records account activity and API calls, so it does not evaluate an architecture or track improvement milestones.`]],slot:1,evidence:[`waf-tool|Available in the AWS Management Console, the AWS Well-Architected Tool provides a trusted framework for you to evaluate your cloud architecture and implement designs that will scale over time.`,`waf-tool|Save point-in-time milestones, implement improvements, and track changes to measure progress.`]}),t({id:`pillar-plaza-008`,building:`pillar-plaza`,d:2,stem:`A small IT team needs a NoSQL database for a new product but has no experience operating one. The team wants to focus on product development rather than provisioning and managing resources. Which approach BEST follows the Performance efficiency design principles?`,correct:[`Consume NoSQL as a managed service with Amazon DynamoDB`,`The principle is to democratize advanced technologies by consuming them as a service, so the team focuses on the product instead of running the database.`],wrong:[[`Install and operate a NoSQL database cluster on Amazon EC2 instances`,`The team would have to learn, host and run the technology itself, which is what the principle says to avoid.`],[`Send the team on training so it can run a self-managed cluster on premises`,`This keeps the operational burden with the team and delays the product, so it does not meet the requirement.`],[`Place the database on the largest memory-optimized Amazon EC2 instance available`,`A bigger instance does nothing about the lack of operating expertise, so the team still manages the database.`]],slot:2,evidence:[`waf-perf-dp|Rather than asking your IT team to learn about hosting and running a new technology, consider consuming the technology as a service.`,`waf-perf-dp|In the cloud, these technologies become services that your team can consume, permitting your team to focus on product development rather than resource provisioning and management.`]}),e({id:`pillar-plaza-009`,building:`pillar-plaza`,d:3,stem:`A company is launching a product with unpredictable demand. In the past it bought hardware for a guessed peak and tested only on a small environment. The team wants to follow the general Well-Architected design principles. Which TWO actions BEST meet this goal? (Choose two.)`,correct:[[`Scale capacity in and out automatically with demand instead of guessing a peak`,`The framework says to stop guessing capacity because you can use as much or as little as you need and scale automatically.`],[`Create a production-scale test environment on demand, run the tests, then decommission it`,`In the cloud, a production-scale test environment can be created on demand and removed after testing, so tests match production.`]],wrong:[[`Reserve fixed capacity sized for the highest forecast for the next three years`,`This is a guessed capacity and leaves idle resources or limited capacity if the guess is wrong.`],[`Keep testing on the small fixed environment to save effort`,`The small environment does not test at production scale, which the principle recommends.`],[`Treat the first architecture as final and avoid changes`,`The framework recommends evolutionary architectures that change as the business evolves, not static one-time decisions.`],[`Skip simulated production events to avoid disrupting the team`,`The framework recommends game days that simulate events, which show where improvements are needed.`]],slots:[1,4],evidence:[`waf-general-dp|You can use as much or as little capacity as you need, and scale in and out automatically.`,`waf-general-dp|In the cloud, you can create a production-scale test environment on demand, complete your testing, and then decommission the resources.`]}),t({id:`pillar-plaza-010`,building:`pillar-plaza`,d:3,stem:`A company moves a critical application from on premises. Its old tests only proved that the workload ran in one scenario, and recovery plans were never exercised. The team must validate that the new workload can recover from failures before a real incident occurs. Which action BEST follows the Reliability design principles?`,correct:[`Use automation to simulate failures and rehearse the recovery procedures regularly`,`The Reliability pillar says you can test how a workload fails and validate recovery, using automation to simulate failures, which exposes failure pathways before a real event.`],wrong:[[`Run load tests that confirm the workload performs well while every component is healthy`,`Load tests on a healthy system show performance, but they never exercise failure or recovery.`],[`Write detailed recovery runbooks and file them without running them`,`Untested procedures are not validated, which is the weakness in the old approach.`],[`Assume Multi-AZ deployment removes the need to exercise recovery`,`Multi-AZ helps resilience, but it does not validate the recovery procedures or expose failure pathways.`]],slot:3,evidence:[`waf-rel-dp|In the cloud, you can test how your workload fails, and you can validate your recovery procedures.`,`waf-rel-dp|You can use automation to simulate different failures or to recreate scenarios that led to failures before.`]})],i=[t({id:`safe-harbor-account-001`,building:`safe-harbor-account`,d:1,stem:`A founder has just created a new AWS account and signs in with the email address and password used to create it for all daily administration. A security reviewer asks for the MOST secure way to handle daily work. Which solution meets this requirement?`,correct:[`Create an administrative user in AWS IAM Identity Center and reserve root for tasks that need it`,`The root user has complete access and should be used only for tasks that require root-level permissions, while an administrative user handles daily work.`],wrong:[[`Keep using the root user for everything, because it already has every permission needed`,`The root user has complete access to the account, so daily use exposes the most powerful credentials to everyday risk.`],[`Share the root user password with the whole team so any administrator can sign in`,`Sharing the most privileged credentials widens exposure and makes it unclear who acted.`],[`Create access keys for the root user and give them to administrators for the CLI`,`AWS strongly recommends not creating root access keys because the root user has full access, including billing information.`]],slot:0,evidence:[`iam-root-user|We recommend that you configure an administrative user in AWS IAM Identity Center to perform daily tasks and access AWS resources.`,`iam-root-user|Use the root user only to perform the tasks that require root-level permissions.`]}),t({id:`safe-harbor-account-002`,building:`safe-harbor-account`,d:2,stem:`A company wants to add MFA to the root user of a new account. The security team wants the MOST phishing-resistant option. Which MFA type should it choose?`,correct:[`A FIDO security key`,`FIDO-based security keys use public key cryptography and resist phishing, man-in-the-middle and replay attacks.`],wrong:[[`A virtual authenticator application generating one-time codes`,`This is a TOTP-based option, which AWS describes as a weaker level of security than FIDO-based authenticators.`],[`A hardware TOTP token`,`It is a TOTP-based option, which is a weaker level of security than a FIDO-based authenticator.`],[`A longer root user password and no second factor`,`A password alone is a single factor and does not add the second authentication factor that MFA provides.`]],slot:1,evidence:[`iam-mfa|These FIDO-based authenticators use public key cryptography and are resistant to phishing, man-in-the-middle, and replay attacks, providing a stronger level of security than TOTP-based options.`]}),t({id:`safe-harbor-account-003`,building:`safe-harbor-account`,d:2,stem:`A team sets a monthly cost limit for its practice account and wants an email warning BEFORE the money is actually spent, as soon as AWS expects the limit to be exceeded. Which solution meets this requirement?`,correct:[`An AWS Budgets cost budget with a notification on forecasted spend`,`A budget can alert on forecasted spend before it accrues, and a cost budget tracks spending against the limit.`],wrong:[[`An AWS Budgets cost budget that notifies only when actual spend reaches the limit`,`An actual-spend alert fires after the cost has accrued, so it is not a warning before the money is spent.`],[`An AWS Budgets usage budget on one service's usage amount`,`A usage budget tracks usage against a threshold rather than the monthly cost limit.`],[`An AWS Budgets RI utilization budget`,`This alerts when Reserved Instance utilization falls below a threshold and says nothing about total spend.`]],slot:2,evidence:[`budgets-managing|You can choose to be alerted for both actual (after accruing) and forecasted (before accruing) spends.`,`budgets-managing|Cost budgets: Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`]}),e({id:`safe-harbor-account-004`,building:`safe-harbor-account`,d:3,stem:`A training company gives students a sandbox AWS account. It needs an email warning when spend reaches 80 percent of the monthly budget and an automatic way to stop students from provisioning more resources, with the LEAST manual effort. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a cost budget with a notification at 80 percent of the budgeted amount`,`A cost budget alerts when costs approach a threshold, and the notification can be set at 80 percent.`],[`Configure a budget action that applies a custom IAM policy denying the ability to provision additional resources`,`A budget can apply an action automatically, such as an IAM policy that denies provisioning more resources.`]],wrong:[[`Create an RI utilization budget for the account`,`It alerts on Reserved Instance utilization, which does not track spend against the monthly budget.`],[`Review the monthly invoice after the month closes`,`This happens after the spend and requires manual effort, so it does not warn at 80 percent or block provisioning.`],[`Create a usage budget for a single service`,`It covers one service's usage and does not warn on the account's total spend.`],[`Ask an administrator to check spending weekly and remove permissions by hand`,`This is manual and can miss the threshold, which fails the least-manual-effort requirement.`]],slots:[3,1],evidence:[`budgets-managing|Then, you can configure your notifications for 80 percent of your budgeted amount and apply an action.`,`budgets-managing|For example, you could automatically apply a custom IAM policy that denies you the ability to provision additional resources within an account.`]}),t({id:`safe-harbor-account-005`,building:`safe-harbor-account`,d:3,stem:`In a standalone AWS account, a misconfigured bucket policy on an Amazon S3 bucket denies all principals access to the bucket, including every administrator. The company must regain access with the LEAST workaround. Which action should it take?`,correct:[`Sign in as the root user and remove the bucket policy`,`Editing or deleting a bucket policy that denies all principals is a task that requires root user credentials.`],wrong:[[`Sign in as an AWS IAM Identity Center administrator and delete the bucket policy`,`The policy denies all principals, so an administrative user cannot remove it.`],[`Create a new IAM user with administrator permissions and delete the bucket policy`,`The new user is still a principal that the policy denies, so the delete is blocked.`],[`Attach an IAM policy that allows the delete action to the administrator role`,`An explicit deny in a resource-based policy overrides any allow, so adding an allow does not remove the lock-out.`]],slot:3,evidence:[`iam-root-user|Edit or delete an Amazon S3 bucket policy that denies all principals.`,`iam-root-user|Some tasks can only be performed when you sign in as the root user of an account.`,`iam-eval-logic|An explicit deny in either of these policies overrides the allow.`]}),t({id:`safe-harbor-account-006`,building:`safe-harbor-account`,d:2,stem:`A team wants a budget alert when total usage hours of a single service go above a limit, regardless of what that usage costs. Which type of AWS Budgets budget is the BEST fit?`,correct:[`A usage budget`,`A usage budget sets usage limits for one or more services and notifies when usage approaches or exceeds the threshold.`],wrong:[[`A cost budget`,`A cost budget sets spending limits, so it follows the price of the usage instead of the usage itself.`],[`An RI utilization budget`,`This alerts when Reserved Instance utilization falls below a threshold, which is a different measurement.`],[`A Savings Plans coverage budget`,`This alerts when the share of eligible usage covered by Savings Plans falls below a level, not when usage grows past a limit.`]],slot:0,evidence:[`budgets-managing|Usage budgets: Establish usage limits for one or more services and get notified when usage approaches or exceeds your set threshold.`,`budgets-managing|Cost budgets: Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`]}),t({id:`safe-harbor-account-007`,building:`safe-harbor-account`,d:2,stem:`The root user of a company's AWS account is tied to the personal mailbox of the founder, who is about to leave. If AWS must contact the account owner, replies could be delayed. What is the BEST change to the root user credentials?`,correct:[`Use an email address managed by the business that forwards to a group of users`,`A group address reduces the risk of delays when individuals are away or have left the business.`],wrong:[[`Keep the founder's mailbox and ask the founder to share its password with the team`,`Sharing a mailbox password spreads access to the root user recovery path and keeps the dependence on one person.`],[`Create access keys for the root user and give them to the new account owner`,`Root access keys are discouraged because the root user has full access, and they do not change who receives account email.`],[`Keep the personal email and set a mail rule to forward to a colleague`,`The root email would still be tied to the departing person's mailbox, which stays a single point of failure.`]],slot:1,evidence:[`iam-root-best-practices|Use an email address that is managed by your business and forwards received messages directly to a group of users.`,`iam-root-best-practices|If AWS must contact the owner of the account, this approach reduces the risk of delays in responding, even if individuals are on vacation, out sick, or have left the business.`]}),e({id:`safe-harbor-account-008`,building:`safe-harbor-account`,d:2,stem:`A company is hardening the root user of a new account. Which TWO actions BEST follow AWS recommendations for the root user? (Choose two.)`,correct:[[`Register multi-factor authentication for the root user`,`Because the root user can perform privileged actions, MFA is added as a second authentication factor in addition to the email address and password.`],[`Do not create access keys for the root user`,`AWS strongly recommends against root access keys because the root user has full access, including billing information.`]],wrong:[[`Share the root password in a team chat so any engineer can sign in`,`Sharing the password widens exposure of the most privileged credential.`],[`Store the root password only in a tool that runs inside the same account`,`AWS advises against storing the root password with tools that depend on services in an account accessed with that same password, because losing the password locks you out of the tool.`],[`Use the root user for daily deployments to avoid role switching`,`The root user should be used only for tasks that require it, not for everyday work.`]],slots:[2,4],evidence:[`iam-root-best-practices|Because a root user can perform privileged actions, it's crucial to add MFA for the root user as a second authentication factor in addition to the email address and password as sign-in credentials.`,`iam-root-best-practices|We strongly recommend that you do not create access keys for your root user because the root user has full access to all AWS services and resources in the account, including billing information.`]}),t({id:`safe-harbor-account-009`,building:`safe-harbor-account`,d:1,stem:`A startup has created a standalone AWS account that is not part of an organization. The root user signs in with only an email address and password, and the founders worry that a stolen password would give an attacker complete access to the account. Which action protects the root user MOST effectively?`,correct:[`Register a multi-factor authentication (MFA) device for the root user`,`MFA adds a second authentication factor to the email address and password, and it can be enabled for the root user of standalone accounts.`],wrong:[[`Create root user access keys and store them in AWS Secrets Manager`,`AWS recommends against root access keys, and keys do not add a second factor to the root user sign-in.`],[`Create an IAM user with the AdministratorAccess policy and keep using the root user for daily work`,`An administrative user does not protect the root sign-in, and the root user should be used only for tasks that require it.`],[`Create an AWS Budgets forecast alert for the account`,`A budget warns about spending and does nothing to protect the root user sign-in from a stolen password.`]],slot:2,evidence:[`iam-mfa|You can enable MFA for the AWS account root user of all AWS accounts, including standalone accounts, management accounts, and member accounts, as well as for your IAM users.`,`iam-root-best-practices|Because a root user can perform privileged actions, it's crucial to add MFA for the root user as a second authentication factor in addition to the email address and password as sign-in credentials.`]}),t({id:`safe-harbor-account-010`,building:`safe-harbor-account`,d:3,stem:`A company is about to let an engineer create billable resources in a new practice account. It wants the root user protected, daily access that avoids long-term credentials, and an early warning if spend drifts. Which combination meets these requirements MOST effectively?`,correct:[`Enable root user MFA, use an IAM Identity Center administrative user daily, and set a forecasted-spend cost budget`,`It protects the root user with a second factor, uses temporary credentials for daily work and warns before spend accrues.`],wrong:[[`Create root user access keys, share one IAM user's keys for daily work, and read the invoice monthly after it arrives`,`Root and shared long-term keys expose the most powerful access, and a monthly invoice review is not an early warning.`],[`Use the root user daily with a very long password, and create a usage budget for one single service`,`Daily use of the root user is discouraged, and a usage budget on one service does not warn about overall spend.`],[`Enable root user MFA, give the engineer long-term IAM user keys, and rely on RI utilization budget alerts`,`Long-term keys are not temporary credentials, and RI utilization alerts do not warn about drifting spend.`]],slot:0,evidence:[`iam-root-user|We recommend that you configure an administrative user in AWS IAM Identity Center to perform daily tasks and access AWS resources.`,`iam-best-practices|Require human users to use federation with an identity provider to access AWS using temporary credentials`,`budgets-managing|You can choose to be alerted for both actual (after accruing) and forecasted (before accruing) spends.`,`iam-root-best-practices|Because a root user can perform privileged actions, it's crucial to add MFA for the root user as a second authentication factor in addition to the email address and password as sign-in credentials.`]})],a=[t({id:`surveyors-grid-001`,building:`surveyors-grid`,d:1,stem:`A company is creating a new VPC for a large analytics platform. It wants a single IPv4 CIDR block with the HIGHEST number of addresses that a VPC allows. Which CIDR block should the architect specify?`,correct:[`10.0.0.0/16`,`A /16 netmask is the largest block size a VPC accepts, with 65,536 addresses.`],wrong:[[`10.0.0.0/8`,`A /8 block would hold more addresses, but it is larger than the largest block size a VPC allows.`],[`10.0.0.0/24`,`A /24 block holds only 256 addresses, far fewer than a /16 block, so it does not meet the requirement for the highest number.`],[`10.0.0.0/28`,`A /28 block is the smallest size a VPC allows, with 16 addresses, which is the opposite of the requirement.`]],slot:0,evidence:[`vpc-cidr-blocks|The allowed block size is between a /16 netmask (65,536 IP addresses) and /28 netmask (16 IP addresses).`]}),t({id:`surveyors-grid-002`,building:`surveyors-grid`,d:1,stem:`A company is creating a VPC and wants to follow the documented recommendation to use a private IPv4 range defined in RFC 1918. Which CIDR block BEST meets this recommendation?`,correct:[`172.20.0.0/16`,`The block lies inside 172.16.0.0 to 172.31.255.255, the 172.16.0.0/12 private range from RFC 1918.`],wrong:[[`172.32.0.0/16`,`The 172.16.0.0/12 private range ends at 172.31.255.255, so this block is outside RFC 1918 and is publicly routable address space.`],[`192.169.0.0/16`,`The private range is 192.168.0.0/16, so 192.169.0.0/16 is outside RFC 1918.`],[`11.0.0.0/16`,`The private range is 10.0.0.0/8, so a block starting at 11 is outside RFC 1918.`]],slot:1,evidence:[`vpc-cidr-blocks|When you create a VPC, we recommend that you specify a CIDR block from the private IPv4 address ranges as specified in RFC 1918.`,`vpc-cidr-blocks|172.16.0.0 - 172.31.255.255 (172.16/12 prefix)`]}),e({id:`surveyors-grid-003`,building:`surveyors-grid`,d:2,stem:`A company's automation script assigns static private IP addresses to EC2 instances in a subnet with the CIDR block 10.0.4.0/24. Which TWO addresses are reserved and cannot be assigned to an instance? (Choose two.)`,correct:[[`10.0.4.2`,`It is the base of the subnet range plus two, one of the first four addresses AWS reserves in every subnet, so it cannot be assigned to an instance.`],[`10.0.4.255`,`It is the last address in the subnet CIDR block, which is reserved.`]],wrong:[[`10.0.4.4`,`Only the first four addresses (.0 to .3) are reserved, so .4 is the first address an instance can use.`],[`10.0.4.100`,`It sits in the middle of the range and is available to instances.`],[`10.0.4.254`,`Only the very last address (.255) is reserved at the end of the block, so .254 is available to instances.`]],slots:[1,4],evidence:[`vpc-subnet-sizing|The first four IP addresses and the last IP address in each subnet CIDR block are not available for your use, and they cannot be assigned to a resource, such as an EC2 instance.`,`vpc-subnet-sizing|We also reserve the base of each subnet range plus two for all CIDR blocks in the VPC.`]}),t({id:`surveyors-grid-004`,building:`surveyors-grid`,d:2,stem:`A company is adding a subnet to an existing VPC for a fleet of 30 EC2 instances that each need one private IPv4 address. The subnet should be no larger than necessary. Which subnet CIDR block is the MINIMUM size that meets these requirements?`,correct:[`10.0.8.0/26`,`A /26 block has 64 addresses, and after the 5 reserved ones 59 remain, enough for 30 instances.`],wrong:[[`10.0.8.0/28`,`A /28 block has 16 addresses, and only 11 remain after the reserved ones, which is fewer than 30.`],[`10.0.8.0/27`,`A /27 block has 32 addresses, but after the 5 reserved ones only 27 remain, which is fewer than 30.`],[`10.0.8.0/25`,`A /25 block has 128 addresses and would work, but it is larger than the minimum that meets the requirement.`]],slot:2,evidence:[`vpc-subnet-sizing|The first four IP addresses and the last IP address in each subnet CIDR block are not available for your use, and they cannot be assigned to a resource, such as an EC2 instance.`,`vpc-cidr-blocks|The allowed block size is between a /16 netmask (65,536 IP addresses) and /28 netmask (16 IP addresses).`]}),t({id:`surveyors-grid-005`,building:`surveyors-grid`,d:2,stem:`A VPC has the CIDR block 10.0.0.0/16 and already contains the subnets 10.0.0.0/24 and 10.0.1.0/24. An architect must add a third subnet to the same VPC. Which subnet CIDR block can the architect use?`,correct:[`10.0.2.0/24`,`It is a subset of the VPC block and does not overlap either existing subnet.`],wrong:[[`10.0.0.128/25`,`It lies inside 10.0.0.0/24, and the CIDR blocks of subnets in one VPC cannot overlap.`],[`10.0.1.0/24`,`It is identical to an existing subnet, so it overlaps, which is not allowed.`],[`10.1.0.0/24`,`It is outside the 10.0.0.0/16 VPC block; a subnet block must be the same as or a subset of the VPC block.`]],slot:3,evidence:[`vpc-subnet-sizing|The CIDR block of a subnet can be the same as the CIDR block for the VPC (to create a single subnet in the VPC), or a subset of the CIDR block for the VPC (to create multiple subnets in the VPC).`,`vpc-subnet-sizing|If you create more than one subnet in a VPC, the CIDR blocks of the subnets cannot overlap.`]}),t({id:`surveyors-grid-006`,building:`surveyors-grid`,d:3,stem:`A company runs workloads in a VPC whose primary CIDR block is 10.0.0.0/24, and every subnet is almost out of free IP addresses. The company must add room for many more EC2 instances with the LEAST disruption to the running workloads. Which solution meets these requirements?`,correct:[`Associate the additional CIDR block 10.2.0.0/16 with the VPC and create new subnets in it`,`The VPC keeps running and the new block adds address space, so the existing workloads are not touched.`],wrong:[[`Edit the VPC to change its primary CIDR block from /24 to /16`,`The size of an existing CIDR block cannot be increased or decreased.`],[`Disassociate the primary CIDR block and associate a larger block in its place`,`The primary CIDR block the VPC was created with cannot be disassociated.`],[`Create a new VPC with a larger CIDR block and migrate every workload to it`,`It would give the space, but moving every workload is the most disruptive option.`]],slot:0,evidence:[`vpc-cidr-blocks|After you've created your VPC, you can associate additional IPv4 CIDR blocks with the VPC.`,`vpc-cidr-blocks|You cannot increase or decrease the size of an existing CIDR block.`,`vpc-cidr-blocks|you cannot disassociate the CIDR block with which you originally created the VPC (the primary CIDR block)`]}),t({id:`surveyors-grid-007`,building:`surveyors-grid`,d:2,stem:`A company runs a Linux bastion host on EC2. Only administrators on the corporate network 198.51.100.0/24 should be able to connect over SSH. Which inbound security group rule is the MOST secure way to meet this requirement?`,correct:[`Protocol TCP, port 22, source 198.51.100.0/24`,`SSH uses TCP port 22, and limiting the source to the corporate CIDR range allows only those administrators.`],wrong:[[`Protocol TCP, port 22, source 0.0.0.0/0`,`SSH would work, but every address on the internet could reach the port, which is less secure than the corporate range.`],[`Protocol UDP, port 22, source 198.51.100.0/24`,`SSH runs over TCP, so a UDP rule would not allow the administrators to connect.`],[`Protocol TCP, port 3389, source 198.51.100.0/24`,`Port 3389 is the Remote Desktop port, so an SSH connection on port 22 is still blocked.`]],slot:1,evidence:[`ec2-sg-use-cases|To connect to your instance, your security group must have inbound rules that allow SSH access (for Linux instances) or RDP access (for Windows instances).`,`ec2-sg-use-cases|TCP 6 22 (SSH) The public IPv4 address of your computer, or a range of IP addresses in your local network.`,`ec2-sg-use-cases|TCP 6 3389 (RDP) The public IPv4 address of your computer, or a range of IP addresses in your local network.`]}),t({id:`surveyors-grid-008`,building:`surveyors-grid`,d:2,stem:`Administrators can connect to an EC2 instance over SSH but cannot ping it from the corporate network 198.51.100.0/24. The instance security group allows inbound TCP port 22 from that range and still has its default outbound rule. Which change allows ping with the LEAST additional exposure?`,correct:[`Add an inbound ICMP Echo Request rule with the source 198.51.100.0/24`,`Ping uses ICMP, and limiting the source to the corporate range opens the instance to no other addresses.`],wrong:[[`Add an inbound UDP rule for all ports with the source 198.51.100.0/24`,`Ping is carried by ICMP, not UDP, so this opens many ports and still does not allow ping.`],[`Add an inbound ICMP Echo Request rule with the source 0.0.0.0/0`,`It would allow ping, but it exposes the instance to ping from every address, not only the corporate range.`],[`Add an outbound ICMP rule with the destination 198.51.100.0/24`,`The incoming echo request is what is blocked, and the default outbound rule already allows all outbound traffic.`]],slot:2,evidence:[`vpc-sg-rules|The most common protocols are 6 (TCP), 17 (UDP), and 1 (ICMP).`,`vpc-sg-rules|For example, use type 8 for ICMP Echo Request or type 128 for ICMPv6 Echo Request.`,`vpc-sg-rules|When you first create a security group, it has an outbound rule that allows all outbound traffic from the resource.`]}),t({id:`surveyors-grid-009`,building:`surveyors-grid`,d:3,stem:`A company has two VPCs in different accounts, and both use the primary CIDR block 10.0.0.0/16. The company needs a VPC peering connection between them and is able to rebuild one of the VPCs. Which solution BEST meets these requirements?`,correct:[`Create a replacement VPC in one account with a non-overlapping CIDR block, migrate its resources, and peer the VPCs`,`Peering requires VPCs with no matching or overlapping CIDR blocks, and a replacement VPC removes the overlap.`],wrong:[[`Associate the secondary CIDR block 10.1.0.0/16 with one VPC and peer using only that range`,`Peering fails if any CIDR block overlaps, and the 10.0.0.0/16 primary blocks still overlap.`],[`Create the peering connection and add route table entries for 10.0.0.0/16 in both VPCs`,`The connection cannot be created while the CIDR blocks overlap, so routes have nothing to use.`],[`Create the peering connection and open the ports in the security groups of both VPCs`,`Security group rules do not change the CIDR overlap that blocks the peering connection.`]],slot:3,evidence:[`peering-basics|You cannot create a VPC peering connection between VPCs that have matching or overlapping IPv4 or IPv6 CIDR blocks.`,`peering-basics|If you have multiple IPv4 CIDR blocks, you can't create a VPC peering connection if any of the CIDR blocks overlap, even if you intend to use only the non-overlapping CIDR blocks or only IPv6 CIDR blocks.`]}),e({id:`surveyors-grid-010`,building:`surveyors-grid`,d:3,stem:`A company has a VPC with the CIDR block 10.0.0.0/16 and needs two new, non-overlapping subnets. Each subnet must provide at least 500 usable IPv4 addresses for instances. Which TWO CIDR blocks can the architect assign to the two subnets? (Choose two.)`,correct:[[`10.0.0.0/23`,`A /23 block has 512 addresses, and 507 remain after the 5 reserved ones, which is at least 500.`],[`10.0.2.0/23`,`A /23 block leaves 507 usable addresses, and it does not overlap 10.0.0.0/23.`]],wrong:[[`10.0.4.0/24`,`A /24 block has 256 addresses and 251 usable ones, which is fewer than 500.`],[`10.0.8.0/24`,`A /24 block leaves only 251 usable addresses, which is fewer than 500.`],[`10.1.0.0/23`,`It is large enough, but it is outside the 10.0.0.0/16 VPC block, and a subnet block must be a subset of the VPC block.`]],slots:[0,3],evidence:[`vpc-subnet-sizing|The first four IP addresses and the last IP address in each subnet CIDR block are not available for your use, and they cannot be assigned to a resource, such as an EC2 instance.`,`vpc-subnet-sizing|If you create more than one subnet in a VPC, the CIDR blocks of the subnets cannot overlap.`]})],o=[t({id:`town-charter-001`,building:`town-charter`,d:1,stem:`A candidate sitting a certification exam has a few minutes left and four unanswered questions. The candidate cannot rule out any option on two of them. The exam guide states how unanswered questions are scored. Which action is the BEST use of the remaining time?`,correct:[`Select an answer for every remaining question, guessing where needed`,`Unanswered questions are scored as incorrect and there is no penalty for guessing, so an answer can only help.`],wrong:[[`Leave the two uncertain questions blank so they are not counted`,`Blank questions are scored as incorrect, so leaving them blank gains nothing and removes any chance of credit.`],[`Answer only the two questions that seem certain and leave the rest`,`Unanswered questions are scored as incorrect, so skipping them throws away possible credit.`],[`Answer only questions with four options, because guessing on others is penalized`,`There is no penalty for guessing on any question, so the question type gives no reason to skip.`]],slot:0,evidence:[`exam-guide|Unanswered questions are scored as incorrect; there is no penalty for guessing.`]}),t({id:`town-charter-002`,building:`town-charter`,d:1,stem:`A company needs to create thumbnails every time an image is uploaded to an Amazon S3 bucket. Uploads are unpredictable and sometimes none arrive for hours. The company wants the solution with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Invoke an AWS Lambda function from the S3 upload event`,`Lambda runs code in response to events and manages server maintenance, capacity provisioning, scaling and patching, so the team does not operate servers.`],wrong:[[`Run a fleet of Amazon EC2 instances that poll the bucket for new images`,`The company must patch, scale and monitor the instances, which adds the operational work the requirement tries to avoid.`],[`Run a self-managed container cluster on Amazon EC2 instances that scans the bucket`,`The cluster and its instances must be managed and sized by the company, which is more overhead than an event-driven function.`],[`Run a single Amazon EC2 instance with a cron job that checks for new objects`,`The instance needs patching and monitoring, and one instance is a single point of failure that the company must handle.`]],slot:1,evidence:[`lambda-welcome|Lambda automatically manages the underlying infrastructure – including server maintenance, capacity provisioning, scaling, and patching – so you can focus on your application logic.`,`lambda-welcome|You write a handler function, connect it to a trigger (API Gateway, Amazon S3, Amazon SQS, EventBridge, and 200+ other AWS services), and Lambda executes it.`]}),t({id:`town-charter-003`,building:`town-charter`,d:2,stem:`A company runs a nightly data-conversion batch job on Amazon EC2. The job can be interrupted and restarted, and its start time is flexible within the night. Several options would work. Which option is the MOST cost-effective?`,correct:[`Run the job on Amazon EC2 Spot Instances`,`Spot Instances use spare capacity at steep discounts and suit applications that are flexible about when they run and can be interrupted, which matches this job.`],wrong:[[`Run the job on On-Demand Instances`,`On-Demand Instances work, but they give up the discount available for a job that tolerates interruption.`],[`Buy three-year Reserved Instances for the job`,`A long commitment pays for capacity around the clock, though the job runs only part of each night.`],[`Run the job on Dedicated Hosts`,`Dedicated Hosts add cost for physical server isolation, which the job does not need.`]],slot:2,evidence:[`ec2-spot|Spot Instances are a cost-effective choice if you can be flexible about when your applications run and if your applications can be interrupted.`,`ec2-spot|Because Spot Instances enable you to request unused EC2 instances at steep discounts, you can lower your Amazon EC2 costs significantly.`]}),t({id:`town-charter-004`,building:`town-charter`,d:2,stem:`An application on Amazon EC2 instances must read objects from an Amazon S3 bucket. The security team wants the MOST secure way to provide AWS credentials to the application. Which solution meets this requirement?`,correct:[`Attach an IAM role to the instances through an instance profile`,`The application receives temporary credentials from the role, so no long-term access keys are stored or rotated.`],wrong:[[`Store an IAM user access key in a configuration file on each instance`,`A long-term key on disk can be copied and must be rotated by hand, which weakens security.`],[`Embed an IAM user access key in the application code`,`A long-term key in code is exposed to anyone who can read the code or its repository.`],[`Create access keys for the account root user and use them in the application`,`The root user has complete access and should be used only for tasks that need it, so this far exceeds what the application needs.`]],slot:3,evidence:[`iam-best-practices|Require workloads to use temporary credentials with IAM roles to access AWS`,`ec2-iam-roles|We designed IAM roles so that your applications can securely make API requests from your instances, without requiring you to manage the security credentials that the applications use.`]}),t({id:`town-charter-005`,building:`town-charter`,d:2,stem:`A web tier on Amazon EC2 sees traffic that rises and falls unpredictably during the day. The company wants to meet performance requirements as demand changes, without paying for idle capacity, and with the LEAST manual intervention. Which solution meets these requirements?`,correct:[`Use an Auto Scaling group with a target tracking policy on average CPU`,`The group adds capacity when the metric rises and removes it when demand falls, with no operator action.`],wrong:[[`Run a fixed fleet of instances sized for the highest expected traffic of the year`,`A fixed peak-sized fleet pays for idle capacity whenever demand is lower.`],[`Have an operator add and remove instances by hand whenever an alarm fires`,`The scaling is manual, which fails the requirement for the least manual intervention.`],[`Use scheduled scaling with fixed capacity changes at set times each day`,`Scheduled actions suit predictable patterns, but this traffic is unpredictable, so capacity will not follow demand.`]],slot:0,evidence:[`asg-target-tracking|A target tracking scaling policy automatically scales the capacity of your Auto Scaling group based on a target metric value.`,`asg-what-is|Using auto scaling allows you to maintain application availability and reduce costs by adding capacity to handle peak loads and removing capacity when demand is lower.`]}),t({id:`town-charter-006`,building:`town-charter`,d:2,stem:`A company keeps compliance documents in Amazon S3. Each document is read about once a month, but when it is needed it must open within milliseconds. The company wants the MOST cost-effective storage class that meets this access pattern. Which storage class should it use?`,correct:[`S3 Standard-IA`,`S3 Standard-IA is designed for long-lived, infrequently accessed data and still provides millisecond access.`],wrong:[[`S3 Standard`,`S3 Standard meets the access time, but it is designed for data accessed more than once a month and is not the lowest-cost fit for monthly reads.`],[`S3 Glacier Flexible Retrieval`,`Objects must be restored before use, with retrieval times of minutes to hours, so they do not open within milliseconds.`],[`S3 Glacier Deep Archive`,`Retrieval takes hours and objects are not available for real-time access, so it fails the millisecond requirement.`]],slot:1,evidence:[`s3-storage-classes|Long-lived, infrequently accessed data (once a month) with millisecond access`,`s3-storage-classes|S3 Standard-IA and S3 One Zone-IA storage classes are designed for long-lived and infrequently accessed data.`,`s3-storage-classes|S3 Standard-IA and S3 One Zone-IA objects are available for millisecond access (similar to the S3 Standard storage class).`,`s3-storage-classes|However, S3 Glacier Flexible Retrieval and S3 Glacier Deep Archive objects are archived, and not available for real-time access.`]}),e({id:`town-charter-007`,building:`town-charter`,d:2,stem:`A company stores private reports in an Amazon S3 bucket. An application on Amazon EC2 reads the reports, and only the company's own IAM principals may read them. Which TWO actions MOST effectively restrict access? (Choose two.)`,correct:[[`Turn on S3 Block Public Access for the bucket`,`Block Public Access settings override policies and permissions that would otherwise make the data public.`],[`Grant the application read access through an IAM role with least-privilege permissions`,`A role limits access to authorized principals and grants only the permissions the task needs.`]],wrong:[[`Grant the application's role the s3:* action on all resources`,`The role would be able to do far more than read these reports, which breaks the least-privilege requirement.`],[`Turn on server-side encryption with Amazon S3 managed keys (SSE-S3) for the bucket`,`Encryption at rest protects stored data, but it does not decide which principals may read the objects, so it does not restrict access.`],[`Share one IAM user's long-term access keys with every team`,`Shared long-term keys cannot be tied to one principal and are harder to protect than role credentials.`]],slots:[2,4],evidence:[`s3-block-public-access|S3 Block Public Access settings override these policies and permissions so that you can limit public access to these resources.`,`iam-best-practices|Apply least-privilege permissions When you set permissions with IAM policies, grant only the permissions required to perform a task.`]}),t({id:`town-charter-008`,building:`town-charter`,d:3,stem:`A company runs a stateless web application on Amazon EC2 instances that all run in one Availability Zone, behind an Application Load Balancer. The application must keep serving users if one Availability Zone becomes unavailable. Many designs would work. Which design is the MOST cost-effective?`,correct:[`Use an Auto Scaling group across two Availability Zones behind the load balancer`,`The group balances instances across two zones, the load balancer spreads traffic across them, and the group launches instances in the remaining zone if one becomes unavailable, without a permanently idle duplicate.`],wrong:[[`Keep one Availability Zone and move every instance to the largest instance size`,`A larger instance does not survive the loss of its zone, so it fails the availability requirement.`],[`Run a permanent full-size copy of the whole fleet in a second AWS Region`,`It meets availability but pays for a full idle duplicate, which costs more than needed.`],[`Run a full-size fleet in each of three Availability Zones at all times`,`It meets availability but carries a full idle fleet in every zone, which costs more than needed.`]],slot:2,tags:[],evidence:[`asg-benefits|If one Availability Zone becomes unavailable, Amazon EC2 Auto Scaling can launch instances in another one to compensate.`,`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`]}),t({id:`town-charter-009`,building:`town-charter`,d:3,stem:`A company's checkout site calls an order-processing service on Amazon EC2 synchronously. During flash sales the service is overwhelmed and some orders are lost. Which change MOST effectively prevents orders from being lost during traffic spikes?`,correct:[`Place an Amazon SQS queue between the site and the service so the service polls it`,`A durable queue decouples the two components and buffers requests, so orders wait in the queue instead of being lost when the service is busy, and the queue scales to absorb spikes.`],wrong:[[`Increase the timeout of the site's request to the order-processing service`,`The site waits longer, but an overwhelmed service still drops work and orders can still be lost.`],[`Move the order-processing service to a larger Amazon EC2 instance type`,`A larger instance raises the ceiling, but spikes can still exceed it and nothing buffers the excess orders.`],[`Put Amazon CloudFront in front of the order endpoint to cache requests`,`CloudFront caches content at edge locations and does not hold orders for later processing.`]],slot:3,evidence:[`sqs-what-is|Amazon Simple Queue Service (Amazon SQS) offers a secure, durable, and available hosted queue that lets you integrate and decouple distributed software systems and components.`,`sqs-what-is|Scalability – Amazon SQS can process each buffered request independently, scaling transparently to handle any load increases or spikes without any provisioning instructions.`]}),e({id:`town-charter-010`,building:`town-charter`,d:3,stem:`A company is moving a containerized web application and its relational database from self-managed servers to AWS. The database must stay relational. Leadership wants the LEAST operational overhead for both the application tier and the database tier. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Run the containers on Amazon ECS with AWS Fargate`,`Fargate runs containers without having to manage servers or clusters of EC2 instances.`],[`Move the database to Amazon RDS`,`Amazon RDS is a managed database service that handles backups, software patching, automatic failure detection and recovery.`]],wrong:[[`Run the containers on a self-managed cluster of Amazon EC2 instances`,`The company must manage and patch the servers and the cluster, which keeps the overhead.`],[`Install the database engine on Amazon EC2 instances and script the backups`,`The company must handle software install, patching and backups itself, which keeps the overhead.`],[`Convert the relational database to Amazon DynamoDB tables`,`DynamoDB is not a relational database, so this does not meet the requirement to keep the database relational and would force the application to be redesigned.`]],slots:[0,3],evidence:[`fargate-ecs|AWS Fargate is a technology that you can use with Amazon ECS to run containers without having to manage servers or clusters of Amazon EC2 instances.`,`rds-what-is|Amazon RDS manages backups, software patching, automatic failure detection, and recovery.`]})],s=Object.values(Object.assign({"../../content/questions/square/lookout-tower.ts":n,"../../content/questions/square/pillar-plaza.ts":r,"../../content/questions/square/safe-harbor-account.ts":i,"../../content/questions/square/surveyors-grid.ts":a,"../../content/questions/square/town-charter.ts":o})).flat();export{s as questions};